import{_ as a,o as r,c as d,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const o="/llamatron/assets/chains.B6C7moTS.svg",e="/llamatron/assets/chain_editor.BqOIvBWI.svg",u=JSON.parse('{"title":"Chains","description":"","frontmatter":{},"headers":[],"relativePath":"CHAINS.md","filePath":"CHAINS.md"}'),i={name:"CHAINS.md"};function s(h,t,c,p,l,g){return r(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="chains" tabindex="-1">Chains <a class="header-anchor" href="#chains" aria-label="Permalink to &quot;Chains&quot;">​</a></h1><p>A chain is a list of generators that runs on clips. This page covers how chains run, where they are placed, and the Chains page.</p><h2 id="how-a-chain-runs" tabindex="-1">How a Chain Runs <a class="header-anchor" href="#how-a-chain-runs" aria-label="Permalink to &quot;How a Chain Runs&quot;">​</a></h2><p>A chain runs its generators one after another, from top to bottom, each working on what the generator before it made. An arpeggiator followed by an AutoRatchet therefore arpeggiates first and then chops every arpeggiated note into repeats, while an AutoRatchet followed by an arpeggiator ratchets the chords first and then arpeggiates the repeats. Chains run whenever a clip plays or exports.</p><h2 id="chain-placement" tabindex="-1">Chain Placement <a class="header-anchor" href="#chain-placement" aria-label="Permalink to &quot;Chain Placement&quot;">​</a></h2><p>A clip names the chains it runs, and so can a scene and a track:</p><ul><li>a <strong>clip&#39;s</strong> chains shape that one clip;</li><li>a <strong>scene&#39;s</strong> chains shape every clip of the scene;</li><li>a <strong>track&#39;s</strong> chains shape every clip the track plays, in every scene.</li></ul><p>A clip runs its own chains first, then its scene&#39;s, then its track&#39;s, and a chain named twice runs twice. The clip page, the Scene page and the track editor each have a Chains field that opens the list.</p><h2 id="chains-page" tabindex="-1">Chains Page <a class="header-anchor" href="#chains-page" aria-label="Permalink to &quot;Chains Page&quot;">​</a></h2><p><img src="'+o+'" alt="The Chains page"></p><p>Press <code>C</code> on the main screen to open the Chains page.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Add a chain</td></tr><tr><td><code>Enter</code></td><td>Edit its steps</td></tr><tr><td><code>N</code></td><td>Rename it, which updates every clip</td></tr><tr><td><code>C</code></td><td>Copy it</td></tr><tr><td><code>M</code></td><td>Pick it up: <code>↑↓</code> carry it, and <code>Enter</code> drops it</td></tr><tr><td><code>S</code></td><td>Sort the list by name</td></tr><tr><td><code>Bksp</code></td><td>Delete it, once no clip uses it</td></tr></tbody></table><h2 id="chain-editor" tabindex="-1">Chain Editor <a class="header-anchor" href="#chain-editor" aria-label="Permalink to &quot;Chain Editor&quot;">​</a></h2><p><img src="'+e+'" alt="The chain editor"></p><p><img src="'+e+'" alt="The chain editor"></p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><code>A</code></td><td>Add a step: any generator, made first on the Generators page</td></tr><tr><td><code>Enter</code></td><td>Change the step to another generator</td></tr><tr><td><code>C</code></td><td>Copy the step</td></tr><tr><td><code>M</code></td><td>Pick it up: <code>↑↓</code> carry it, and <code>Enter</code> drops it</td></tr><tr><td><code>Bksp</code></td><td>Remove it</td></tr><tr><td><code>N</code></td><td>Rename the chain, which updates every clip that uses it</td></tr></tbody></table>',16)])])}const C=a(i,[["render",s]]);export{u as __pageData,C as default};
